function calculateBedVolume() {
  const length = parseFloat(document.getElementById("length").value);
  const width = parseFloat(document.getElementById("width").value);
  const height = parseFloat(document.getElementById("height").value);
  let result;

  if (isNaN(length) || isNaN(width) || isNaN(height)) {
    result = "Please enter all dimensions.";
  } else {
    const cubicInches = length * width * height;
    const cubicFeet = cubicInches / 1728;
    result = `You will need approximately ${cubicFeet.toFixed(2)} cubic feet of soil.`;
  }

  document.getElementById("bedResult").textContent = result;
}

function convertCuFtToCuYds() {
  const cubicFeet = parseFloat(document.getElementById("cuFtInput").value);
  let result;

  if (isNaN(cubicFeet)) {
    result = "Please enter a valid number.";
  } else {
    const cubicYards = cubicFeet / 27;
    result = `${cubicFeet} cubic feet = ${cubicYards.toFixed(2)} cubic yards`;
  }

  document.getElementById("cuYdResult").textContent = result;
}

function calculateCubicYards() {
  const length = parseFloat(document.getElementById("lengthFeet").value);
  const width = parseFloat(document.getElementById("widthFeet").value);
  const depth = parseFloat(document.getElementById("depthInches").value);

  let result;
  if (isNaN(length) || isNaN(width) || isNaN(depth)) {
    result = "Please enter all dimensions.";
  } else {
    // Convert to cubic feet: L x W x (D in inches ÷ 12)
    const cubicFeet = length * width * (depth / 12);
    // Convert to cubic yards: cu ft ÷ 27
    const cubicYards = cubicFeet / 27;
    result = `You will need approximately ${cubicYards.toFixed(2)} cubic yards of material.`;
  }

  document.getElementById("yardResult").textContent = result;
}

function convertVolume() {
  const value = parseFloat(document.getElementById("inputValue").value);
  const type = document.getElementById("conversionType").value;
  let result;

  if (isNaN(value)) {
    result = "Please enter a valid number.";
  } else {
    if (type === "gallonsToCubicFeet") {
      result = (value * 0.133681).toFixed(2) + " cubic feet";
    } else {
      result = (value * 7.48052).toFixed(2) + " gallons";
    }
  }

  document.getElementById("result").textContent = result;
}

