function calculateBags() {
  const length = parseFloat(document.getElementById("areaLength").value);
  const width = parseFloat(document.getElementById("areaWidth").value);
  const depth = parseFloat(document.getElementById("depthInches").value);
  const bagVolume = parseFloat(document.getElementById("bagVolume").value);

  let result;
  if (isNaN(length) || isNaN(width) || isNaN(depth) || isNaN(bagVolume) || bagVolume <= 0) {
    result = "Please enter valid numbers for all fields.";
  } else {
    const cubicFeet = length * width * (depth / 12);
    const bagsNeeded = Math.ceil(cubicFeet / bagVolume);
    result = `You will need approximately ${bagsNeeded} bags.`;
  }

  document.getElementById("bagsResult").textContent = result;
}
